def max_value_on_paths(N: int, grid_values: List[Tuple[int, int, int]]) -> int:
    # Initialize the dynamic programming table
    dp = [[[0, 0] for _ in range(N)] for _ in range(N)]

    # Populate the dynamic programming table
    for value in grid_values:
        x, y, v = value
        dp[x][y] = [v, 0]

    # Fill in the table using the recurrence relation
    for i in range(N):
        for j in range(N):
            if dp[i][j][1] != 0:
                continue
            # Compute the maximum sum of values collected on two paths
            # that pass through grid cell (i, j)
            max_sum = max(dp[i][j][0], dp[i][j][1])
            for k in range(N):
                if dp[k][j][1] != 0:
                    max_sum = max(max_sum, dp[i][j][0] + dp[k][j][1])
            dp[i][j][1] = max_sum

    # Return the maximum sum of values collected on two paths
    return dp[N-1][N-1][1]

