    terms = []
    # Iterate over the coefficients and degrees
    for i, coeff in enumerate(coeffs):
        # Check if the coefficient is zero
        if coeff == 0:
            # Skip the term if the coefficient is zero
            continue
        # Initialize the term with the coefficient
        term = str(coeff)
        # Check if the coefficient is negative
        if coeff < 0:
            # Add a minus sign to the term if the coefficient is negative
            term = '-' + term
        # Check if the degree is 0 (constant term)
        if i == 0:
            # Add the constant term to the list of terms
            terms.append(term)
        else:
            # Add the variable part to the term based on the degree
            if i == 1:
                var = 'x'
            else:
                var = f'x^{i}'
            # Add the variable part and the term to the list of terms
            terms.append(term + var)
    # Join the terms without spaces
    return ''.join(terms)

